"""Packaged RAM-bench smoke check using generated bytes and an in-memory UART.

This model checks application integration. It is not ECU instruction emulation
or evidence that SRAM wiring or a physical diagnostic connection works.
"""
from bisect import bisect_right
import json
import os
from pathlib import Path
import sys

from .core import CalibrationDefinition
from .dde5_patch_test import PATCH_WORDS
from .dde5_ram_calibration import (BOUNDARIES, DIRECTORY_ADDRESS, DIRECTORY_BYTES,
                                    EXTERNAL_BASE, build_ram_plan, run_ram_bench)
from .serial_transport import encode_request, xor_checksum


class _Clock:
    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now

    def sleep(self, seconds):
        self.now += seconds


class _SyntheticEcu:
    """Separate immutable flash, manager state and calibration shadow blocks."""

    def __init__(self, baseline, *, echo=True):
        self.baseline = baseline
        self.echo = echo
        self.clock = _Clock()
        self.memory = {}
        self.shadow = {}
        self.ports = []
        self.payloads = []
        self.checksum = None
        self.checksum_statuses = []
        self.store(DIRECTORY_ADDRESS, b''.join(value.to_bytes(4, 'big') for value in BOUNDARIES))
        for address, value in PATCH_WORDS.items():
            self.store(address, value.to_bytes(2, 'big'))
        self.put(0x3F9856, 5, 1)
        self.put(0x3F9844, 1)

    def store(self, address, values):
        self.memory.update({address + offset: value for offset, value in enumerate(values)})

    def put(self, address, value, width=4):
        self.store(address, value.to_bytes(width, 'big'))

    def load(self, address, count):
        return bytes(self.memory.get(target, self.baseline[target - 0x800000]
                     if 0x800000 <= target < 0x900000 else 0)
                     for target in range(address, address + count))

    def get(self, address, width=4):
        return int.from_bytes(self.load(address, width), 'big')

    @staticmethod
    def block_index(address):
        index = bisect_right(BOUNDARIES, address) - 1
        if not 0 <= index < len(BOUNDARIES) - 1:
            raise AssertionError('Synthetic request is outside the calibration directory.')
        return index

    def mapped(self, address, count):
        result = bytearray()
        for target in range(address, address + count):
            index = self.block_index(target)
            if self.get(0x3FE544) and index in self.shadow:
                result.append(self.shadow[index][target - BOUNDARIES[index]])
            else:
                result.extend(self.load(target, 1))
        return bytes(result)

    def response(self, payload):
        if payload == b'\x1A\x92':
            return b'\x5A\x92' + b'0281010565'
        if payload == b'\x1A\x94':
            return b'\x5A\x94' + b'1037361830'
        if payload[0] == 0x23:
            assert len(payload) == 5
            return b'\x63' + self.load(int.from_bytes(payload[1:4], 'big'), payload[4])
        if payload == b'\x10\x86\x10':
            self.shadow.clear()
            self.put(0x3F9840, 3, 1)
            self.store(0x3FE540, b'\x01\x00')
            self.put(0x3FE544, 0)
            self.put(0x3FE54C, EXTERNAL_BASE)
            self.put(0x3FE550, 1, 1)
            self.put(0x3FE554, 0x3F9FD4)
            self.put(0x3FE558, EXTERNAL_BASE + DIRECTORY_BYTES)
            return b'\x50\x86\x10'
        if payload[0] == 0x3D:
            assert len(payload) == 6 and payload[4] == 1
            target = int.from_bytes(payload[1:4], 'big')
            index = self.block_index(target)
            if index not in self.shadow:
                start, end = BOUNDARIES[index:index + 2]
                self.shadow[index] = bytearray(self.load(start, end - start))
                internal = self.get(0x3FE554)
                if internal + end - start <= 0x3FA178:
                    self.put(0x3FE554, internal + end - start)
                else:
                    self.put(0x3FE558, self.get(0x3FE558) + end - start)
            self.shadow[index][target - BOUNDARIES[index]] = payload[5]
            return b'\x7D'
        if payload[:2] == b'\x80\x90':
            assert len(payload) == 3 and payload[2] in (0, 1)
            self.put(0x3FE544, EXTERNAL_BASE - DIRECTORY_ADDRESS if payload[2] else 0)
            return b'\xC0' + payload[1:]
        if payload[:2] == b'\x31\x01':
            assert len(payload) == 10 and self.checksum is None
            start = int.from_bytes(payload[2:5], 'big')
            end = int.from_bytes(payload[5:8], 'big')
            expected = int.from_bytes(payload[8:10], 'big')
            actual = sum(self.mapped(start, end - start + 1)) & 0xFFFF
            self.put(0x3FE562, 0, 2)
            self.put(0x3FE541, 6, 1)
            self.checksum = [actual, expected, True]
            return b'\x71\x01'
        if payload == b'\x33\x01':
            assert self.checksum is not None
            actual, expected, busy = self.checksum
            if busy:
                self.checksum[2] = False
                response = b'\x7F\x33\x23'
            else:
                self.put(0x3FE562, actual, 2)
                self.put(0x3FE541, 0, 1)
                self.checksum = None
                response = b'\x73\x01' if actual == expected else b'\x7F\x33\xFA'
            self.checksum_statuses.append(response)
            return response
        raise AssertionError('Unexpected synthetic RAM bench request: ' + payload.hex())

    def factory(self, **options):
        port = _MemoryUart(self, options)
        self.ports.append(port)
        return port


class _MemoryUart:
    """A transport object without an OS handle or any device-opening code."""

    def __init__(self, ecu, options):
        self.ecu, self.options = ecu, options
        self.port = options['port']
        self.dtr = self.rts = True
        self.baudrate = options['baudrate']
        self.is_open = False
        self.closed = False
        self.buffer = bytearray()

    def open(self):
        assert self.port == 'COM8' and self.baudrate == 9600
        assert self.dtr is False and self.rts is False
        assert (self.options['bytesize'], self.options['parity'], self.options['stopbits']) == (8, 'E', 1)
        assert not any(self.options[key] for key in ('xonxoff', 'rtscts', 'dsrdtr'))
        self.is_open = True

    def close(self):
        self.is_open = False
        self.closed = True

    def reset_input_buffer(self):
        self.buffer.clear()

    @property
    def in_waiting(self):
        return len(self.buffer)

    def read(self, count):
        result = bytes(self.buffer[:count])
        del self.buffer[:count]
        if not result:
            self.ecu.clock.sleep(.020)
        return result

    def write(self, request):
        payload = request[4:-1]
        assert request == encode_request(payload) and self.baudrate == 9600
        self.ecu.payloads.append(payload)
        response = self.ecu.response(payload)
        body = b'\xB8\xF1\x12' + bytes([len(response)]) + response
        if self.ecu.echo:
            self.buffer.extend(request)
        self.buffer.extend(body + bytes([xor_checksum(body)]))
        return len(request)


def _bench_case(baseline, plan, change):
    ecu = _SyntheticEcu(baseline, echo=not change)
    report = run_ram_bench(
        'COM8', plan=plan, hardware={
            'capacity_bytes': 32768,
            'reference': 'Generated simulation: wiring/bank/capacity declaration is not physical evidence',
            'confirmed': True},
        probe_change=change, echo=ecu.echo, serial_factory=ecu.factory,
        clock=ecu.clock, sleep=ecu.clock.sleep)
    original = baseline[plan['table']['file_offset']:plan['table']['file_offset'] + plan['probe_bytes']]
    writes = [payload for payload in ecu.payloads if payload[0] == 0x3D]
    expected_values = ([original[:1], bytes([original[0] ^ 1]), original[:1]]
                       if change else [original[:1]])
    exact_writes = ([payload[5:] for payload in writes] == expected_values
                    and all(int.from_bytes(payload[1:4], 'big') == plan['probe_address']
                            and payload[4] == 1 for payload in writes))
    shadow_unchanged = all(bytes(data) == ecu.load(BOUNDARIES[index], len(data))
                           for index, data in ecu.shadow.items())
    statuses = set(ecu.checksum_statuses)
    checks = {
        'bench_passed': report['status'] == 'passed',
        'reference_restored': report['restore']['reference_page'] == 'verified' and ecu.get(0x3FE544) == 0,
        'write_restored': report['restore']['write'] == ('verified' if change else 'not_needed'),
        'exact_bounded_writes': exact_writes,
        'shadow_matches_original_after_run': bool(ecu.shadow) and shadow_unchanged,
        'flash_unchanged': ecu.load(plan['probe_address'], len(original)) == original,
        'busy_match_and_mismatch_statuses': statuses == {b'\x7F\x33\x23', b'\x73\x01', b'\x7F\x33\xFA'},
        'virtual_port_closed': len(ecu.ports) == 1 and ecu.ports[0].closed and not ecu.ports[0].is_open,
        'only_9600_baud': all(frame['host_baud'] == 9600 for frame in report['frames']),
        'no_flash_reset_or_auth': not any(payload[0] in (0x11, 0x27, 0x34, 0x36, 0x37)
                                         for payload in ecu.payloads),
        'no_recovery_required': not report['restore']['power_cycle_required']
                                and not report['restore']['restoration_required'],
    }
    return {'ok': all(checks.values()), 'checks': checks, 'echo': ecu.echo, 'report': report}


def run_check(path):
    """Write a JSON smoke report and return its success flag; never use a device."""
    os.environ.setdefault('QT_QPA_PLATFORM', 'offscreen')
    from . import __version__
    output = {'ok': False, 'version': __version__, 'frozen': bool(getattr(sys, 'frozen', False)),
              'simulation': 'generated BIN and high-level RAM/UART model; not ECU instruction emulation',
              'physical_port_opened': False, 'network_used': False}
    os_port_attempts = 0
    gui_bench_calls = 0
    previous_serial = None
    serial = None
    try:
        import serial
        previous_serial = serial.Serial
        def reject_os_port(*_args, **_kwargs):
            nonlocal os_port_attempts
            os_port_attempts += 1
            raise AssertionError('The synthetic self-check must not open an OS serial port.')
        serial.Serial = reject_os_port
        baseline = bytes(range(256)) * 4096
        definition = CalibrationDefinition('Synthetic Main SOI', 'Generated smoke fixture',
                                             'Self-check', 0xEA80C, 2, 2, profile_id='361830')
        plan = build_ram_plan(baseline, definition, capacity_bytes=32768)
        from PySide6.QtWidgets import QApplication
        from . import dde5_ram_calibration_gui as ram_gui
        app = QApplication.instance() or QApplication([])
        previous_bench = ram_gui.run_ram_bench
        def reject_gui_bench(*_args, **_kwargs):
            nonlocal gui_bench_calls
            gui_bench_calls += 1
            raise AssertionError('Opening the RAM bench dialog must not start a check.')
        dialog = None
        try:
            ram_gui.run_ram_bench = reject_gui_bench
            dialog = ram_gui.Dde5RamCalibrationDialog(baseline, definition, image_name='generated.FLS')
            dialog.show()
            app.processEvents()
            output['gui_no_automatic_connection'] = (
                dialog.plan is not None and dialog.worker is None and not dialog._busy
                and not dialog.port.text() and not dialog.run_button.isEnabled()
                and not dialog.hardware_confirmed.isChecked() and not dialog.probe_change.isChecked())
        finally:
            if dialog is not None:
                if dialog.worker is not None:
                    dialog.worker.request_cancel()
                    dialog.worker.wait(1000)
                    app.processEvents()
                dialog.close()
                app.processEvents()
            ram_gui.run_ram_bench = previous_bench
        output['modes'] = {'unchanged': _bench_case(baseline, plan, False),
                           'changed_byte': _bench_case(baseline, plan, True)}
        output['gui_backend_calls'] = gui_bench_calls
        output['os_port_attempts'] = os_port_attempts
        output['ok'] = (output['gui_no_automatic_connection'] and gui_bench_calls == 0
                         and os_port_attempts == 0 and all(case['ok'] for case in output['modes'].values()))
    except Exception as exc:
        output.update(error=f'{type(exc).__name__}: {exc}', os_port_attempts=os_port_attempts,
                      gui_backend_calls=gui_bench_calls)
    finally:
        if serial is not None and previous_serial is not None:
            serial.Serial = previous_serial
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(output, indent=2) + '\n', encoding='utf-8')
    return output['ok']
